	static void assertAllAlternatives(LmdbBenchmarkPlanQualityAudit audit, Map<Value, Long> expected, String label) {
		assertTrue(audit.alternativeCount() > 0, "real planner must retain a selected alternative");
		long selected = audit.auditResult().alternatives().stream().filter(a -> a.selectedByPolicy()).count();
		assertEquals(1L, selected, "the ordinary selected alternative must be present exactly once");
		for (int index = 0; index < audit.alternativeCount(); index++) {
			Map<Value, Long> actual = new HashMap<>();
			try (var rows = audit.evaluate(index)) {
				while (rows.hasNext()) {
					actual.merge(rows.next().getValue("s"), 1L, Long::sum);
				}
			}
			receipt(label, "alternative=" + index + ";selected="
					+ audit.auditResult().alternatives().get(index).selectedByPolicy() + ";bag=" + actual);
			assertEquals(expected, actual, label + ";alternative=" + index);
		}
	}

	static Map<Value, Long> queryBag(SailRepository repository, String query, boolean includeInferred) {
		Map<Value, Long> result = new HashMap<>();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			var prepared = connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			assertTrue(prepared.getIncludeInferred(), "fresh query defaults to benchmark BOTH before override");
			prepared.setIncludeInferred(includeInferred);
			assertEquals(includeInferred, prepared.getIncludeInferred());
			prepared.setMaxExecutionTime(TIMEOUT_SECONDS);
			try (var rows = prepared.evaluate()) {
				while (rows.hasNext()) {
					result.merge(rows.next().getValue("s"), 1L, Long::sum);
				}
			}
		}
		receipt("ordinary-query", "store=" + repository.getSail().getClass().getSimpleName()
				+ ";includeInferred=" + includeInferred + ";bag=" + result);
		return result;
	}

	static Map<Value, Long> statementBag(SailDatasetTripleTermSource source) {
		Map<Value, Long> result = new HashMap<>();
		try (var rows = source.getStatements(null, P, O)) {
			while (rows.hasNext()) {
				result.merge(rows.next().getSubject(), 1L, Long::sum);
			}
		}
		return result;
	}

	static long assertOwner(SailDatasetTripleTermSource source, boolean includeInferred, String label) {
		LmdbPhysicalReadComposition composition = SailDatasetReadComposition.resolve(source,
				LmdbPhysicalReadComposition.class, LmdbPhysicalReadComposition::union).orElseThrow();
		int expected = includeInferred ? FrontierLeafProbe.BOTH_PLANES : FrontierLeafProbe.EXPLICIT;
		assertEquals(expected, composition.frontierPlaneMask(), label);
		var occurrences = composition.planeOccurrences();
		assertEquals(includeInferred ? 2 : 1, occurrences.size(), label);
		if (includeInferred) {
			assertFalse(occurrences.get(0).explicit(), "normal ordered BOTH source starts with inferred");
			assertTrue(occurrences.get(1).explicit(), "normal ordered BOTH source ends with explicit");
		} else {
			assertTrue(occurrences.get(0).explicit());
		}
		var transaction = occurrences.get(0).owner().pinnedReadTxn().orElseThrow();
		var dictionary = occurrences.get(0).owner().pinnedValueSnapshot().orElseThrow();
		for (var occurrence : occurrences) {
			assertSame(transaction, occurrence.owner().pinnedReadTxn().orElseThrow(), label);
			assertSame(dictionary, occurrence.owner().pinnedValueSnapshot().orElseThrow(), label);
		}
		assertTrue(dictionary.isPairedWith(transaction), "dictionary must authenticate its actual transaction");
		long epoch = source.getSnapshotEpoch().orElseThrow();
		receipt(label, "mask=" + composition.frontierPlaneMask() + ";epoch=" + epoch
				+ ";revision=" + transaction.snapshotRevision() + ";occurrences=" + occurrences.size()
				+ ";sameTransaction=true;sameDictionary=true;dictionaryPaired=true");
		return epoch;
	}

	static void assertClosed(SailDatasetTripleTermSource source, String label) {
		assertThrows(IllegalStateException.class, () -> SailDatasetReadComposition.resolve(source,
				LmdbPhysicalReadComposition.class, LmdbPhysicalReadComposition::union), label);
		receipt(label, "actual composition resolution rejected after logical owner close");
	}

	private static void receipt(String label, String fields) {
		System.out.println("AUDIT_POPULATION_RECEIPT " + label + ";" + fields);
	}

