		void assertInitialOrdinaryBags() {
			assertEquals(Map.of(A, 1L), queryBag(oracle, QUERY, false));
			assertEquals(Map.of(A, 1L, B, 1L), queryBag(oracle, QUERY, true));
			assertEquals(queryBag(oracle, QUERY, false), queryBag(repository, QUERY, false));
			assertEquals(queryBag(oracle, QUERY, true), queryBag(repository, QUERY, true));
		}

		void addExplicit(IRI subject) {
			for (SailRepository target : new SailRepository[] { repository, oracle }) {
				try (SailRepositoryConnection connection = target.getConnection()) {
					connection.add(subject, P, O);
				}
			}
		}

		@Override
		public void close() {
			try {
				repository.shutDown();
			} finally {
				try {
					oracle.shutDown();
				} finally {
					if (previousPinning == null) {
						System.clearProperty(PINNING);
					} else {
						System.setProperty(PINNING, previousPinning);
					}
				}
			}
			receipt("fixture-closed", "LMDB and MemoryStore shutdown complete");
		}
