	/** Independent source ownership control; every dataset comes from the actual store roots. */
	static final class OwnedRead implements AutoCloseable {
		final List<SailSource> branches;
		final SailDataset dataset;
		final SailDatasetTripleTermSource source;

		private OwnedRead(List<SailSource> branches, SailDataset dataset, LmdbStore store) {
			this.branches = List.copyOf(branches);
			this.dataset = dataset;
			source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
		}

		static OwnedRead open(LmdbStore store, boolean includeInferred) {
			List<SailSource> branches = new ArrayList<>();
			List<SailDataset> datasets = new ArrayList<>();
			SailDataset combined = null;
			SailSource explicitRoot = store.getSailStore().getExplicitSailSource();
			try (SailClosable ignoredAdmission = explicitRoot.beginDatasetAcquisition(store.getDefaultIsolationLevel());
					SailDatasetSnapshot.Scope ignoredSnapshot = SailDatasetSnapshot.open()) {
				if (includeInferred) {
					SailSource inferred = store.getSailStore().getInferredSailSource().fork();
					branches.add(inferred);
					datasets.add(inferred.dataset(store.getDefaultIsolationLevel()));
				}
				SailSource explicit = explicitRoot.fork();
				branches.add(explicit);
				datasets.add(explicit.dataset(store.getDefaultIsolationLevel()));
				combined = includeInferred ? SailDatasetReadComposition.union(datasets.get(0), datasets.get(1))
						: datasets.get(0);
				return new OwnedRead(branches, combined, store);
			} catch (RuntimeException | Error failure) {
				if (combined != null) {
					closeAfterFailure(failure, combined);
				} else {
					for (SailDataset acquired : datasets.reversed()) {
						closeAfterFailure(failure, acquired);
					}
				}
				for (SailSource branch : branches.reversed()) {
					closeAfterFailure(failure, branch);
				}
				throw failure;
			}
		}

		@Override
		public void close() {
			Throwable failure = null;
			try {
				dataset.close();
			} catch (RuntimeException | Error cleanup) {
				failure = cleanup;
			}
			for (SailSource branch : branches.reversed()) {
				try {
					branch.close();
				} catch (RuntimeException | Error cleanup) {
					if (failure == null) {
						failure = cleanup;
					} else if (cleanup != failure) {
						failure.addSuppressed(cleanup);
					}
				}
			}
			if (failure instanceof Error fatal) {
				throw fatal;
			}
			if (failure != null) {
				throw (RuntimeException) failure;
			}
		}
	}

	private static void closeAfterFailure(Throwable failure, AutoCloseable closeable) {
		try {
			closeable.close();
		} catch (Exception | Error cleanup) {
			if (cleanup != failure) {
				failure.addSuppressed(cleanup);
			}
		}
	}

	static final class DeliberateConsumerFailure extends RuntimeException {
		private static final long serialVersionUID = 1L;
	}

	/** A supported configured factory consumer fails after receiving, but never replacing, the real source. */
	static final class FailAfterAcquisitionFactory extends DefaultEvaluationStrategyFactory {
		SailDatasetTripleTermSource actualSource;

		@Override
		public EvaluationStrategy createEvaluationStrategy(Dataset dataset, TripleSource tripleSource,
				EvaluationStatistics statistics) {
			assertEquals(SailDatasetTripleTermSource.class, tripleSource.getClass());
			actualSource = (SailDatasetTripleTermSource) tripleSource;
			assertOwner(actualSource, false, "actual legacy helper source before deliberate consumer failure");
			throw new DeliberateConsumerFailure();
		}
	}
